const packGroups=[['证件 / 入境',[['passport','两人护照原件','建议有效期至少余 6 个月；核对姓名与机票完全一致。'],['identity','身份证备用','深圳出发及国内身份核验备用，不能用来代替护照出境泰国。'],['permit','港澳通行证：如已有可备','此次按护照经港往返泰国的第三地过境规则，不把通行证或旅游签注列为必办。'],['ticket','往返电子客票与行程单','保存离线截图；10/7 02:00 是曼谷出发时间。'],['hotel','酒店确认单与英文地址','TDAC 要用首晚地址；保存前台电话与取消期限。'],['tdac','9/30–10/1 完成两人 TDAC','每个人都有确认件，姓名/证件号码核对无误。'],['insurance','旅行保险与资金材料','确认医疗、延误、海上活动保障和境外援助；资金标准按实际入境类别核实。']]],['预订 / 手机',[['transfer','深圳湾机场班车确认','了解深圳湾机场直达服务和 T2 下车点即可；具体公司、乘车方式和班次自行选择。'],['pattaya','芭提雅往返大巴确认','4 日白天去、5 日白天回；4 日住芭提雅，5 日下午返程。'],['massage','按摩门店与两人时段确认','券限定门店，提前预约，安排在 10/3 或 10/5 空闲时段，不挤进返程日。'],['apps','Google Maps / Grab / 翻译','提前登录，下载离线地图；境外网络实际可用。'],['sim','漫游或 eSIM / 电话卡','核对手机兼容性，保留国内号码接验证码。'],['pay','银行卡＋适量现金','核对境外额度、结算币种、PIN；现金分开放。']]],['随身包',[['power','手机、充电线、插头、充电宝','充电宝随身，查航司容量/数量规定；带转换插头。'],['rain','小伞、薄外套、防水袋','飞机和商场冷，十月有阵雨。'],['care','防晒、防蚊、纸巾、湿巾','选择适合自己的用品，防晒按标签使用。'],['med','常用药与处方记录','保留原包装；含受管制成分药物先查泰国携药要求。'],['bag','水瓶、小额零钱、安全小包','贵重物品随身，不挂在椅背或交陌生人保管。']]],['托运行李 / 出门前',[['clothes','轻薄换洗衣物与寺庙长装','按天气穿搭清单，过膝、不透、有袖。'],['shoes','防滑鞋＋快干凉鞋','别只带新鞋和高跟鞋。'],['weight','称重：每人手提 7kg、托运 23kg','以所附订单及航司最新限制为准，液体整理到对应行李。'],['alarm','10/1 晚设手机闹钟','10/2 早上大致 06:30–07:00 出门，闹钟自行决定；10/6 晚去 BKK 另设提醒。'],['offline','保存关键地址与订单离线截图','网页地图需要网络，不能只依赖在线页面。']]]];
function dateInZone(now,zone){return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
function autoDay(){const now=new Date();const z=now>=new Date('2026-10-02T14:55:00+07:00')&&now<new Date('2026-10-07T05:55:00+08:00')?'Asia/Bangkok':'Asia/Shanghai';const date=dateInZone(now,z);return agenda[date]?date:(date<'2026-10-02'?'prep':'2026-10-07');}
function duration(ms){const minutes=Math.max(0,Math.ceil(ms/60000));return (minutes>=1440?Math.floor(minutes/1440)+' 天 ':'')+Math.floor(minutes%1440/60)+' 小时 '+minutes%60+' 分钟';}
function selectDay(key){
 if(key!=='all'&&(!Object.hasOwn(agenda,key)||key==='prep'))throw Error('无效日期');
 document.querySelectorAll('.journey-day').forEach(day=>day.hidden=key!=='all'&&day.id!=='day-'+key);
 document.querySelectorAll('[data-day-filter]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.dayFilter===key)));
 return {date:key};
}
const dayNotes={prep:['出发前，先把关键事项准备好','酒店已订 · 还需确认大巴和入境材料'], '2026-10-02':['出发，入住曼谷','深圳湾 → 香港机场 → BKK → A-ONE'], '2026-10-03':['曼谷半日，下午留空','卧佛寺 → 泰餐 → 回酒店休息'], '2026-10-04':['去芭提雅，住一晚','退房 → 大巴 → PAYAA → 海边晚餐'], '2026-10-05':['白天回曼谷','真理寺可选 → 退房 → 大巴 → Metropole'], '2026-10-06':['退房休息，晚上去机场','白天留空 · 21:00–21:30 出发参考 · 23:00 前到 BKK'], '2026-10-07':['凌晨起飞，回深圳','02:00 BKK 起飞 → 05:55 香港落地 → 南山']};
function renderDashboard(){
 const now=new Date(),key=autoDay(),a=agenda[key];
 document.getElementById('live-clock').textContent='2026.10.2—10.7 · 两个人 · 四晚酒店已订';
 const next=key==='prep'?null:a.events.find(x=>x[0]&&new Date(x[0])>now);
 document.getElementById('view-mode').textContent=key==='prep'?'出发前':'今天 · '+key.slice(5).replace('-','/');
 document.getElementById('next-title').textContent=key==='prep'?'曼谷 → 芭提雅住一晚 → 曼谷':next?next[2]:dayNotes[key][0];
 document.getElementById('next-note').textContent=key==='prep'?'10/2–3 曼谷 · 10/4 芭提雅 · 10/5 回曼谷 · 10/6晚去机场':dayNotes[key][1];
 const countdown=document.getElementById('countdown');
 countdown.textContent=key==='prep'?'距 10/2 起飞还有 '+duration(new Date('2026-10-02T12:45:00+08:00')-now):next?'距 '+next[1]+' 还有 '+duration(new Date(next[0])-now):'';
 countdown.hidden=!countdown.textContent;
 document.getElementById('jump-today').href='#day-'+(key==='prep'?'2026-10-02':key);
 document.getElementById('jump-today').textContent=key==='prep'?'往下看每天去哪玩 ↓':'跳到今天的安排 ↓';
}
function renderFullPlan(){
 const list=document.getElementById('daily-timeline');list.replaceChildren();
 for(const [key,a] of Object.entries(agenda)){
  if(key==='prep')continue;
  const day=document.createElement('section');day.className='journey-day';day.id='day-'+key;
  const heading=document.createElement('h2');heading.textContent=(key==='prep'?'出发前':key.slice(5).replace('-','/'))+' · '+dayNotes[key][0];day.append(heading);
  const table=document.createElement('table');table.className='itinerary-table';
  const thead=document.createElement('thead');const labels=document.createElement('tr');
  for(const label of ['时间','安排']){const th=document.createElement('th');th.scope='col';th.textContent=label;labels.append(th);}thead.append(labels);table.append(thead);
  const body=document.createElement('tbody');
  a.events.forEach(x=>{
   const row=document.createElement('tr');const timeCell=document.createElement('td');const time=document.createElement('time');time.textContent=x[1];if(x[0])time.dateTime=x[0];timeCell.append(time);
   const content=document.createElement('td');const title=document.createElement('strong');
   const hasLink=x[4].startsWith('http')||['#iconsiam','#pattaya','#food'].includes(x[4]);
   if(hasLink){const link=document.createElement('a');link.href=x[4];link.textContent=x[2];if(x[4].startsWith('http')){link.target='_blank';link.rel='noreferrer';}title.append(link);}else title.textContent=x[2];
   const note=document.createElement('div');note.className='event-note';note.textContent=x[3];content.append(title,note);row.append(timeCell,content);body.append(row);
  });table.append(body);day.append(table);
  if(key!=='prep'&&key!=='2026-10-07'){
   const id=key==='2026-10-04'?'photel':['2026-10-05','2026-10-06'].includes(key)?'mhotel':'hotel';
   const hotel=document.createElement('a');hotel.className='daily-hotel';hotel.href=placeLink(id);hotel.target='_blank';hotel.rel='noreferrer';hotel.textContent=(key==='2026-10-06'?'退房 / 取行李：':'今晚住：')+points[id][0]+' · Google地图 ↗';day.append(hotel);
  }
  const extra=document.createElement('details');extra.className='day-support';
  const summary=document.createElement('summary');summary.textContent='交通怎么走';extra.append(summary);
  const r=routes[a.route];r.legs.forEach((leg,i)=>{const p=document.createElement('p');p.className='transport-line';p.textContent=points[r.ids[i]][0]+' → '+points[r.ids[i+1]][0]+'：'+leg[0]+' · '+leg[2];extra.append(p);});
  const map=document.createElement('a');map.href='#routes';map.textContent='查看路线地图 ↓';map.addEventListener('click',()=>renderRoute(a.route));extra.append(map);
  day.append(extra);list.append(day);
 }
}
renderFullPlan();renderDashboard();setInterval(renderDashboard,60000);

document.querySelectorAll("[data-day-filter]").forEach(button=>button.addEventListener("click",()=>selectDay(button.dataset.dayFilter)));
